package com.coffeeshop.repository;import com.coffeeshop.dto.RefundCommands;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.RefundModels;import javax.sql.DataSource;import java.math.BigDecimal;import java.sql.*;import java.util.*;public final class JdbcRefundRepository implements RefundRepository{private final DataSource ds;public JdbcRefundRepository(DataSource d){ds=Objects.requireNonNull(d);}public RefundModels.Catalog load(){try(Connection c=ds.getConnection()){return new RefundModels.Catalog(payments(c),refunds(c));}catch(SQLException e){throw fail("Unable to load refund data.",e);}}private List<RefundModels.Payment>payments(Connection c)throws SQLException{String q="SELECT p.payment_id,p.order_id,o.order_number,pm.method_code,pm.method_name,p.amount,p.refunded_amount,p.status,p.paid_at,p.row_version FROM dbo.payments p JOIN dbo.orders o ON o.order_id=p.order_id JOIN dbo.payment_methods pm ON pm.payment_method_id=p.payment_method_id WHERE p.status IN('COMPLETED','PARTIALLY_REFUNDED') ORDER BY p.paid_at DESC";try(PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<RefundModels.Payment>x=new ArrayList<>();while(r.next())x.add(new RefundModels.Payment(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getString(8),r.getTimestamp(9).toLocalDateTime(),r.getBytes(10)));return x;}}private List<RefundModels.Refund>refunds(Connection c)throws SQLException{String q="SELECT pr.payment_refund_id,pr.payment_id,o.order_number,pm.method_name,u.username,pr.amount,pr.reason,pr.reference_number,pr.notes,pr.refunded_at FROM dbo.payment_refunds pr JOIN dbo.payments p ON p.payment_id=pr.payment_id JOIN dbo.orders o ON o.order_id=p.order_id JOIN dbo.payment_methods pm ON pm.payment_method_id=p.payment_method_id JOIN dbo.users u ON u.user_id=pr.refunded_by_user_id ORDER BY pr.refunded_at DESC";try(PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<RefundModels.Refund>x=new ArrayList<>();while(r.next())x.add(new RefundModels.Refund(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getString(7),r.getString(8),r.getString(9),r.getTimestamp(10).toLocalDateTime()));return x;}}public long refund(RefundCommands.Create q){try(Connection c=ds.getConnection()){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);try{String method;BigDecimal total,refunded;byte[]version;try(PreparedStatement s=c.prepareStatement("SELECT pm.method_code,p.amount,p.refunded_amount,p.row_version FROM dbo.payments p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.payment_methods pm ON pm.payment_method_id=p.payment_method_id WHERE p.payment_id=? AND p.status IN('COMPLETED','PARTIALLY_REFUNDED')")){s.setLong(1,q.paymentId());try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalStateException("Payment is no longer refundable.");method=r.getString(1);total=r.getBigDecimal(2);refunded=r.getBigDecimal(3);version=r.getBytes(4);}}if(!Arrays.equals(version,q.paymentVersion()))throw new IllegalStateException("Payment changed. Refresh and try again.");BigDecimal next=refunded.add(q.amount());if(next.compareTo(total)>0)throw new IllegalArgumentException("Refund amount exceeds the remaining refundable amount.");Long shift=null;if("CASH".equals(method)){try(PreparedStatement s=c.prepareStatement("SELECT register_shift_id FROM dbo.register_shifts WITH(UPDLOCK,HOLDLOCK) WHERE opened_by_user_id=? AND status='OPEN'")){s.setLong(1,q.userId());try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalStateException("An open register shift is required for a cash refund.");shift=r.getLong(1);}}}try(PreparedStatement s=c.prepareStatement("UPDATE dbo.payments SET refunded_amount=?,status=?,refunded_at=SYSUTCDATETIME(),updated_at=SYSUTCDATETIME() WHERE payment_id=? AND row_version=?")){s.setBigDecimal(1,next);s.setString(2,next.compareTo(total)==0?"REFUNDED":"PARTIALLY_REFUNDED");s.setLong(3,q.paymentId());s.setBytes(4,q.paymentVersion());if(s.executeUpdate()!=1)throw new IllegalStateException("Payment changed. Refresh and try again.");}long id;try(PreparedStatement s=c.prepareStatement("INSERT dbo.payment_refunds(payment_id,register_shift_id,refunded_by_user_id,amount,reason,reference_number,notes) VALUES(?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,q.paymentId());if(shift==null)s.setNull(2,Types.BIGINT);else s.setLong(2,shift);s.setLong(3,q.userId());s.setBigDecimal(4,q.amount());s.setString(5,q.reason());nullable(s,6,q.reference());nullable(s,7,q.notes());s.executeUpdate();id=key(s);}c.commit();return id;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to record refund.",e);}}private static void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null)s.setNull(i,Types.NVARCHAR);else s.setString(i,v);}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Generated key unavailable");return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
